window.kbPageData["views/entry/k-d924519807fd012a"] = {"key":"entry/k-d924519807fd012a","state":{"route":"entry/k-d924519807fd012a"},"node":{"id":"k-d924519807fd012a","mode":"k","title":"经济增长 4.5%－5%","type":"事实与事件","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["finance"],"主类":["事实与事件"],"出处性质":["机构注释"],"学科":["经济"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"政府工作报告","slug":"94fd2d7ef9a6"}],"directorySummary":"1.经济增长 4.5%－5%\n2016 年，我国将经济增速目标设定为 6.5%—7%，2019 年，则是 6%—6.5%，两年实际分\n别增长 6.8%和 6.1%。今年，预期目标再次以区间形式提出，可谓统筹考虑了国际国内形势，\n兼顾了发展的需要和可能，体现了实事求是、因势利导的思路。","sources":[{"id":"fa16e6adf85d1b87","label":"经济增长 4.5%－5%","topic":"年度政府工作","category":"时政","text":"1.经济增长 4.5%－5%\n2016 年，我国将经济增速目标设定为 6.5%—7%，2019 年，则是 6%—6.5%，两年实际分\n别增长 6.8%和 6.1%。今年，预期目标再次以区间形式提出，可谓统筹考虑了国际国内形势，\n兼顾了发展的需要和可能，体现了实事求是、因势利导的思路。","source":{"doc":"6cbfb01fe723bba64b75","first":22,"last":22,"page":22,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"finance","title":"财政金融与宏观调控"}],"units":{"k-d924519807fd012a":[]}};
